        if re.match(r'^(theorem|lemma|instance|def|abbrev|class|structure|import|open|variable|set_option|@\[|noncomputable|private|protected|section|end|namespace|where|\||exact|refine|apply|intro|constructor|simp|rw )', body):
            out.append((cur,line.rstrip()))
for c,l in out: print(c,'||',l)
print("=== total changed lines:", sum(1 for l in open('/tmp/doc.diff') if l[:1] in '+-' and not l.startswith('+++') and not l.startswith('---')))
